from pathlib import Path
import base64, gzip, json, subprocess, sys, tempfile
if len(sys.argv)!=2: raise SystemExit("usage: patch-v50-0-2.py <project-root>")
root=Path(sys.argv[1]).resolve()
if not (root/"ClassicUO.sln").is_file(): raise SystemExit("ClassicUO.sln missing")
PATCH_B64=""
patch=gzip.decompress(base64.b64decode(PATCH_B64))
with tempfile.NamedTemporaryFile(suffix=".patch",delete=False) as f:
    f.write(patch); name=f.name
try:
    subprocess.run(["git","apply","--whitespace=nowarn",name],cwd=root,check=True)
finally:
    Path(name).unlink(missing_ok=True)
# Active release version: broad text replacement, historical verification evidence stays unchanged.
exts={'.cs','.csproj','.props','.targets','.ps1','.cmd','.py','.json','.js','.md','.txt','.yml','.yaml'}
changed=0
for p in root.rglob('*'):
    if not p.is_file() or p.suffix.lower() not in exts: continue
    rel=p.relative_to(root).as_posix()
    if '/bin/' in '/'+rel or '/obj/' in '/'+rel or rel.startswith('verification/') or p.name.startswith('V50_0_0_') or p.name=='V50_0_0_CHANGELOG.md': continue
    try: t=p.read_text(encoding='utf-8-sig')
    except UnicodeDecodeError: continue
    if '50.0.0' in t:
        p.write_text(t.replace('50.0.0','50.0.2'),encoding='utf-8',newline=''); changed+=1
# Update runtime catalog descriptions used by generator/IDE.
p=root/'src/ClassicUO.Client/YokoDocumentation/Manual/injection-manual-catalog.json'; items=json.loads(p.read_text(encoding='utf-8-sig'))
desc={
'Hide':'v50.0.2: Hide() targets a loaded object; Hide(serial) hides immediately using persistent ClientHidden state. Object remains in World and renderer AllowedToDraw recalculation cannot make it visible again while that instance is client-hidden.',
'InfoGump':'v50.0.2: inspects the newest or explicitly selected real IsFromServer Gump, including GumpID=0, stable InjID, real ButtonID controls and exact raw server layout commands.',
'InfoGumps':'v50.0.2: lists all active IsFromServer Gumps; Yoko index 0 is newest.',
'LastGump':'v50.0.2: always reads the newest active server Gump, independent of stale SelectGump/InfoGump selection.',
'GetGump':'v50.0.2: reads selected/resolved active Gump; button returns real ButtonID and command returns exact raw server layout command.',
'SelectGump':'v50.0.2: selects by stable InjID with index/Serial/GumpID compatibility fallback; does not redefine LastGump.',
'GumpExists':'v50.0.2: tests active IsFromServer Gumps; two-argument Serial/GumpID form accepts 0 as wildcard.',
'SendGumpSelect':'v50.0.2: 1/2/3/4-argument overloads; executes only an existing real Button control. Missing button sends no GumpResponse and does not fake success.',
'CancelGump':'v50.0.2: zero-argument form cancels current WaitGump generation; one-argument compatibility form closes specified simple Gump.'}
for x in items:
    n=x.get('Name')
    if n in desc:
        x['DescriptionRu']=desc[n]; x['DescriptionEn']=desc[n]
p.write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
p=root/'src/ClassicUO.Client/YokoDocumentation/Manual/stealth-uo-api-catalog.json'; obj=json.loads(p.read_text(encoding='utf-8-sig')); arr=obj if isinstance(obj,list) else obj.get('commands',obj.get('Commands',[]))
for x in arr:
    n=x.get('Name')
    if n=='ClientHide':
        x['DescriptionEn']='v50.0.2: hides a real loaded non-player object using persistent ClientHidden state and returns True only on actual success; object remains in World.'; x['DescriptionRu']=x['DescriptionEn']
    elif n=='GetGumpsCount':
        x['DescriptionEn']='v50.0.2: returns active non-ignored server Gump count. Stealth public GumpIndex is oldest to newest; count-1 is newest visible.'; x['DescriptionRu']=x['DescriptionEn']
    elif n in {'AddGumpIgnoreByID','AddGumpIgnoreBySerial'}:
        x['DescriptionEn']=(x.get('DescriptionEn') or '')+' v50.0.2: ignore filtering also remaps indexed readers, GetGumpInfo, close and NumGump actions.'; x['DescriptionRu']=x['DescriptionEn']
p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
# Hard source audit before Windows work.
checks={
'v50.0.2 version':'<Version>50.0.2</Version>' in (root/'src/ClassicUO.Client/ClassicUO.Client.csproj').read_text(encoding='utf-8-sig'),
'persistent hide':'public bool ClientHidden { get; private set; }' in (root/'src/ClassicUO.Client/Game/GameObjects/Views/View.cs').read_text(encoding='utf-8-sig'),
'clienthide result':'case "clienthide": return bridge.ClientHide(Arg(0)) != 0' in (root/'external/InjectionScript/src/InjectionScript/Runtime/InjectionApiUO.cs').read_text(encoding='utf-8-sig'),
'real server gump':'gump.IsFromServer && !gump.IsDisposed' in (root/'src/ClassicUO.Client/Game/Managers/ClassicUOInjectionApiBridge.cs').read_text(encoding='utf-8-sig'),
'raw commands':'gump.ServerCommands = cmdlist.ToArray();' in (root/'src/ClassicUO.Client/Network/PacketHandlers.cs').read_text(encoding='utf-8-sig'),
'send select 4 args':'Action<int, int, int, int>)SendGumpSelect' in (root/'external/InjectionScript/src/InjectionScript/Runtime/InjectionApiUO.cs').read_text(encoding='utf-8-sig'),
'end result hide test':'Hide_PersistsAfterRendererVisibilityRecalculation' in (root/'tests/ClassicUO.UnitTests/Game/Managers/YokoCommandEndToEndTests.cs').read_text(encoding='utf-8-sig'),
'end result gump packet test':'SendGumpSelect_UsesRealButton_AndSendsRealGumpReply' in (root/'tests/ClassicUO.UnitTests/Game/Managers/YokoCommandEndToEndTests.cs').read_text(encoding='utf-8-sig')}
for k,v in checks.items(): print('[PASS]' if v else '[FAIL]',k)
if not all(checks.values()): raise RuntimeError('v50.0.2 source self-audit failed')
print('v50.0.2 core patch applied; version files changed=',changed)
